func TestDVDTitleCopyRetainsClearSectors(t *testing.T) {
	dir := t.TempDir()
	src := filepath.Join(dir, "title.vob")
	dst := filepath.Join(dir, "copy.vob")
	sec := make([]byte, css.SectorSize)
	copy(sec, []byte{0, 0, 1, 0xba})
	sec[0x11] = 0xe0
	sec[300] = 77
	input := bytes.Repeat(sec, 30)
	if err := os.WriteFile(src, input, 0600); err != nil {
		t.Fatal(err)
	}
	if err := copyDVDTitleVOB(context.Background(), src, dst, dir); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(dst)
	if err != nil || !bytes.Equal(got, input) {
		t.Fatal("clear title changed", err)
	}
}
func TestDVDTitleCopyRejectsLateUnrecoverableEncryption(t *testing.T) {
	dir := t.TempDir()
	src := filepath.Join(dir, "title.vob")
	dst := filepath.Join(dir, "copy.vob")
	sec := make([]byte, css.SectorSize)
	copy(sec, []byte{0, 0, 1, 0xba})
	sec[0x11] = 0xe0
	input := bytes.Repeat(sec, 30)
	sec[0x14] = 0x30
	input = append(input, sec...)
	if err := os.WriteFile(src, input, 0600); err != nil {
		t.Fatal(err)
	}
	if err := copyDVDTitleVOB(context.Background(), src, dst, dir); err == nil {
		t.Fatal("late scrambled payload copied as plaintext")
	}
}
func TestDVDTitleCopyCancellation(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	dir := t.TempDir()
	src := filepath.Join(dir, "title.vob")
	if err := os.WriteFile(src, make([]byte, css.SectorSize), 0600); err != nil {
		t.Fatal(err)
	}
	if err := copyDVDTitleVOB(ctx, src, filepath.Join(dir, "copy.vob"), dir); !errors.Is(err, context.Canceled) {
		t.Fatal(err)
	}
}
func TestDVDSystemHeaderFlagsAreNotCSS(t *testing.T) {
	sec := make([]byte, css.SectorSize)
	copy(sec, []byte{0, 0, 1, 0xba})
	sec[0x14] = 0x30
	for _, id := range []byte{0xbb, 0xbe, 0xbf} {
		sec[0x11] = id
		if dvdSectorScrambled(sec) {
			t.Fatal("system packet treated as encrypted")
		}
	}
	sec[0x11] = 0xe0
	if !dvdSectorScrambled(sec) {
		t.Fatal("scrambled video PES missed")
	}
}

// Synthetic sector generated by the inverse-cipher fixture in internal/dvd/css.
const playerCSSFixture = ""

func TestProtectedDVDKeyContinuesAcrossSplitVOBs(t *testing.T) {
	dir := t.TempDir()
	encrypted, err := base64.StdEncoding.DecodeString(playerCSSFixture)
	if err != nil {
		t.Fatal(err)
	}
	var shared *css.Decryptor
	first := filepath.Join(dir, "VTS_01_1.VOB")
	firstOut := filepath.Join(dir, "first-out.vob")
	if err = os.WriteFile(first, encrypted, 0600); err != nil {
		t.Fatal(err)
	}
	if err = copyDVDTitleVOBWithKey(context.Background(), first, firstOut, dir, &shared); err != nil {
		t.Fatal(err)
	}
	if shared == nil {
		t.Fatal("recovered title key not retained")
	}
	// Corrupt the clear pattern used for recovery in a subsequent segment.
	// Its encrypted payload and seed still decrypt using the retained title key.
	later := append([]byte(nil), encrypted...)
	for i := 0x60; i < 0x80; i++ {
		later[i] = byte(i)
	}
	second := filepath.Join(dir, "VTS_01_2.VOB")
	secondOut := filepath.Join(dir, "second-out.vob")
	if err = os.WriteFile(second, later, 0600); err != nil {
		t.Fatal(err)
	}
	if err = copyDVDTitleVOBWithKey(context.Background(), second, secondOut, dir, &shared); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(secondOut)
	if err != nil {
		t.Fatal(err)
	}
	if dvdSectorScrambled(got) {
		t.Fatal("segment remained scrambled")
	}
	for i := 0x80; i < len(got); i++ {
		if got[i] != []byte{0, 0, 1, 0xba}[i%4] {
			t.Fatalf("wrong decrypted payload at %d", i)
		}
	}
}

func TestAutomaticDVDSourceRouting(t *testing.T) {
	root := t.TempDir()
	videoTS := filepath.Join(root, "VIDEO_TS")
	if err := os.Mkdir(videoTS, 0700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(videoTS, "VIDEO_TS.IFO"), []byte("test"), 0600); err != nil {
		t.Fatal(err)
	}
	for _, source := range []string{root, videoTS, filepath.Join(root, "disc.ISO")} {
		if !isDVDPlayerSource(source) {
			t.Fatal("disc bypasses preparation", source)
		}
	}
	if isDVDPlayerSource(filepath.Join(root, "video.mp4")) {
		t.Fatal("ordinary media routed as DVD")
	}
}
